<?php
declare(strict_types=1);
namespace App\Modules\SubcontractBoq\Repositories;
use App\Core\Database\Database;
use App\Modules\SubcontractBoq\DTOs\BoqItemData;
final class SubcontractBoqRepository
{
 public function __construct(private readonly Database $db){}
 public function contract(int $id):?array{$r=$this->db->execute('SELECT id,subcontract_code contract_code,title,pricing_method,status,contract_value,work_section_id FROM subcontracts WHERE id=? LIMIT 1',[$id]);$x=$r instanceof \mysqli_result?$r->fetch_assoc():null;return is_array($x)?$x:null;}
 public function boq(int $id):?array{$r=$this->db->execute('SELECT * FROM subcontract_boqs WHERE subcontract_id=? LIMIT 1',[$id]);$x=$r instanceof \mysqli_result?$r->fetch_assoc():null;return is_array($x)?$x:null;}
 public function create(int $id):int{$this->db->execute("INSERT INTO subcontract_boqs(subcontract_id,status) VALUES(?,'draft')",[$id]);return(int)$this->db->connection()->insert_id;}
 public function sections(int $id):array{$r=$this->db->execute('SELECT s.*,COALESCE(SUM(i.line_total),0) subtotal FROM subcontract_boq_sections s LEFT JOIN subcontract_boq_items i ON i.subcontract_boq_section_id=s.id WHERE s.subcontract_boq_id=? GROUP BY s.id ORDER BY s.sort_order,s.id',[$id]);$rows=$r instanceof \mysqli_result?$r->fetch_all(MYSQLI_ASSOC):[];foreach($rows as &$s)$s['items']=$this->items((int)$s['id']);return$rows;}
 public function items(int $id):array{$r=$this->db->execute('SELECT * FROM subcontract_boq_items WHERE subcontract_boq_section_id=? ORDER BY sort_order,id',[$id]);return$r instanceof \mysqli_result?$r->fetch_all(MYSQLI_ASSOC):[];}
 public function section(int $id):?array{$r=$this->db->execute('SELECT s.*,b.subcontract_id,b.status boq_status FROM subcontract_boq_sections s JOIN subcontract_boqs b ON b.id=s.subcontract_boq_id WHERE s.id=? LIMIT 1',[$id]);$x=$r instanceof \mysqli_result?$r->fetch_assoc():null;return is_array($x)?$x:null;}
 public function item(int $id):?array{$r=$this->db->execute('SELECT i.*,s.subcontract_boq_id,b.subcontract_id,b.status boq_status FROM subcontract_boq_items i JOIN subcontract_boq_sections s ON s.id=i.subcontract_boq_section_id JOIN subcontract_boqs b ON b.id=s.subcontract_boq_id WHERE i.id=? LIMIT 1',[$id]);$x=$r instanceof \mysqli_result?$r->fetch_assoc():null;return is_array($x)?$x:null;}
 public function activeUnit(int $id):?array{$r=$this->db->execute('SELECT id,code,name_ar,symbol_ar FROM units WHERE id=? AND is_active=1 LIMIT 1',[$id]);$x=$r instanceof \mysqli_result?$r->fetch_assoc():null;return is_array($x)?$x:null;}
 public function masters(int $workSectionId):array{$r=$this->db->execute('SELECT id,code,name_ar,symbol_ar FROM units WHERE is_active=1 ORDER BY sort_order');return['units'=>$r instanceof \mysqli_result?$r->fetch_all(MYSQLI_ASSOC):[]];}
 public function addItem(BoqItemData$d,array$u):int{$this->db->execute('INSERT INTO subcontract_boq_items(subcontract_boq_section_id,description,pricing_type,unit_id,unit_name,unit_symbol,quantity,unit_rate,lump_sum_amount,sort_order,notes) SELECT ?,?,?,?,?,?,?,?,?,COALESCE(MAX(sort_order),0)+1,? FROM subcontract_boq_items WHERE subcontract_boq_section_id=?',[$d->sectionId,$d->description,$d->pricingType,$d->unitId,$u['name_ar'],$u['symbol_ar'],$d->quantity,$d->unitRate,$d->lumpSumAmount,$d->notes,$d->sectionId]);return(int)$this->db->connection()->insert_id;}
 public function updateItem(int $id,BoqItemData$d,array$u):void{$this->db->execute('UPDATE subcontract_boq_items SET description=?,pricing_type=?,unit_id=?,unit_name=?,unit_symbol=?,quantity=?,unit_rate=?,lump_sum_amount=?,notes=? WHERE id=?',[$d->description,$d->pricingType,$d->unitId,$u['name_ar'],$u['symbol_ar'],$d->quantity,$d->unitRate,$d->lumpSumAmount,$d->notes,$id]);}
 public function removeItem(int $id):void{$this->db->execute('DELETE FROM subcontract_boq_items WHERE id=?',[$id]);}
 public function countItems(int $id):int{$r=$this->db->execute('SELECT COUNT(*) n FROM subcontract_boq_items i JOIN subcontract_boq_sections s ON s.id=i.subcontract_boq_section_id WHERE s.subcontract_boq_id=?',[$id]);return(int)(($r instanceof \mysqli_result?$r->fetch_assoc():[])['n']??0);}
 public function incompleteItems(int $id):int{$r=$this->db->execute("SELECT COUNT(*) n FROM subcontract_boq_items i JOIN subcontract_boq_sections s ON s.id=i.subcontract_boq_section_id WHERE s.subcontract_boq_id=? AND ((i.pricing_type='quantity' AND (i.unit_id IS NULL OR i.quantity IS NULL OR i.unit_rate IS NULL)) OR (i.pricing_type='lump_sum' AND i.lump_sum_amount IS NULL))",[$id]);return(int)(($r instanceof \mysqli_result?$r->fetch_assoc():[])['n']??0);}
 public function total(int $id):string{$r=$this->db->execute('SELECT COALESCE(SUM(i.line_total),0) total FROM subcontract_boq_items i JOIN subcontract_boq_sections s ON s.id=i.subcontract_boq_section_id WHERE s.subcontract_boq_id=?',[$id]);return(string)(($r instanceof \mysqli_result?$r->fetch_assoc():[])['total']??'0.00');}
 public function approve(int $id,int $user,string $total,bool $sync):void{$this->db->execute("UPDATE subcontract_boqs SET status='approved',approved_at=NOW(),approved_by=? WHERE id=? AND status='draft'",[$user,$id]);if($sync)$this->db->execute('UPDATE subcontracts c JOIN subcontract_boqs b ON b.subcontract_id=c.id SET c.contract_value=? WHERE b.id=?',[$total,$id]);}
}
